import {
  Directive,
  effect,
  inject,
  Input,
  TemplateRef,
  ViewContainerRef
} from '@angular/core';
import { AuthService } from '@core/services/auth.service';

/**
 * Directiva estructural para mostrar/ocultar elementos en plantillas segun los permisos
 * del usuario logueado.
 *
 * Acepta un permission code (string) o un array de codes. Si recibe un array, basta con que
 * el usuario tenga AL MENOS UNO de ellos para que el elemento se renderice (semantica OR).
 *
 * Reactiva: si el usuario hace logout/login o se llama a {@link AuthService.reloadPermissions},
 * la directiva re-evalua y actualiza el DOM automaticamente.
 *
 * <pre>
 *   &lt;button *hasPermission="'USERS_DEACTIVATE'"&gt;Desactivar&lt;/button&gt;
 *   &lt;button *hasPermission="['DOC_DELETE', 'DOC_FORCE_STATE']"&gt;Acciones&lt;/button&gt;
 * </pre>
 */
@Directive({
  selector: '[hasPermission]',
  standalone: true
})
export class HasPermissionDirective {
  private readonly tpl = inject(TemplateRef<unknown>);
  private readonly vcr = inject(ViewContainerRef);
  private readonly auth = inject(AuthService);

  private required: string[] = [];
  private rendered = false;

  constructor() {
    // Re-evalua cada vez que cambia el set de permisos (login, logout, recarga manual).
    effect(() => {
      // Lectura del signal para que el effect dependa de el.
      this.auth.permissions();
      this.update();
    });
  }

  @Input() set hasPermission(value: string | readonly string[] | null | undefined) {
    if (value == null) {
      this.required = [];
    } else if (typeof value === 'string') {
      this.required = [value];
    } else {
      this.required = [...value];
    }
    this.update();
  }

  private update(): void {
    const allowed =
      this.required.length === 0 || this.auth.hasAnyPermission(this.required);

    if (allowed && !this.rendered) {
      this.vcr.createEmbeddedView(this.tpl);
      this.rendered = true;
    } else if (!allowed && this.rendered) {
      this.vcr.clear();
      this.rendered = false;
    }
  }
}
